function stworzMagazyn(poczatkowyStan) {
  let stanMagazynu = poczatkowyStan;
  return {
    dodaj: (ile) => { stanMagazynu += ile; },
    stan: () => stanMagazynu
  };
}

const magazyn = stworzMagazyn(50);
magazyn.dodaj(10);
console.log(magazyn.stan()); // 60
magazyn.dodaj(5);
console.log(magazyn.stan()); // 65

function stworzLogger(prefiks) {
  return (wiadomosc) => console.log(`[${prefiks}] ${wiadomosc}`);
}

const loggerInfo = stworzLogger("INFO");
const loggerBlad = stworzLogger("BLAD");

loggerInfo("Serwer uruchomiony");   // [INFO] Serwer uruchomiony
loggerBlad("Baza danych offline");  // [BLAD] Baza danych offline

function stworzMnoznik(czynnik) {
  return wartosc => wartosc * czynnik;
}

const razyDwa = stworzMnoznik(2);
const razyDziesiec = stworzMnoznik(10);

console.log(razyDwa(7));      // 14
console.log(razyDziesiec(7)); // 70

function stworzSejf() {
  let kod = "1234";
  return {
    sprawdz: (proba) => proba === kod
  };
}

const sejf = stworzSejf();
console.log(sejf.sprawdz("1234")); // true
console.log(sejf.sprawdz("0000")); // false
console.log(sejf.kod); // undefined - kod NIE jest dostepny bezposrednio

function zewnetrzna() {
  let suma = 0;
  return function (a) {
    suma += a;
    return function (b) {
      suma += b;
      return function (c) {
        suma += c;
        return suma;
      };
    };
  };
}

const wynik = zewnetrzna()(1)(2)(3);
console.log(wynik); // 6

function stworzKopilke() {
  let saldoWartosc = 0;
  return {
    wplac: (kwota) => { saldoWartosc += kwota; },
    saldo: () => saldoWartosc
  };
}

const kopilka = stworzKopilke();
kopilka.wplac(20);
console.log(kopilka.saldo()); // 20
kopilka.wplac(15);
console.log(kopilka.saldo()); // 35

function stworzGeneratorPowitan(jezyk) {
  return () => {
    if (jezyk === "pl") return "Czesc";
    if (jezyk === "en") return "Hello";
    return "Hi";
  };
}

const powitaniePL = stworzGeneratorPowitan("pl");
const powitanieEN = stworzGeneratorPowitan("en");

console.log(powitaniePL()); // "Czesc"
console.log(powitanieEN()); // "Hello"

function policzWywolania() {
  let licznik = 0;
  return () => ++licznik;
}

const licz = policzWywolania();
console.log(licz()); // 1
console.log(licz()); // 2
console.log(licz()); // 3
console.log(licz()); // 4

function memoize(fn) {
  const cache = {};
  return function (n) {
    if (n in cache) {
      console.log("cache hit:", n);
      return cache[n];
    }
    cache[n] = fn(n);
    return cache[n];
  };
}

const slowSquare = memoize(n => n * n);
console.log(slowSquare(4)); // 16 (obliczono)
console.log(slowSquare(4)); // cache hit: 4 \n 16
